CREATE TABLE "NotificationTemplate" ("id" TEXT NOT NULL PRIMARY KEY, "templateKey" TEXT NOT NULL, "channel" TEXT NOT NULL, "locale" TEXT NOT NULL DEFAULT 'en-IN', "subject" TEXT NOT NULL DEFAULT '', "body" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'DRAFT', "version" INTEGER NOT NULL DEFAULT 1, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "NotificationDelivery" ("id" TEXT NOT NULL PRIMARY KEY, "templateId" TEXT NOT NULL, "userId" TEXT, "recipient" TEXT NOT NULL, "channel" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'QUEUED', "dedupeKey" TEXT NOT NULL, "variablesJson" TEXT NOT NULL DEFAULT '{}', "providerRef" TEXT NOT NULL DEFAULT '', "attempts" INTEGER NOT NULL DEFAULT 0, "maxAttempts" INTEGER NOT NULL DEFAULT 6, "nextAttemptAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "deliveredAt" DATETIME, "lastError" TEXT NOT NULL DEFAULT '', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "NotificationDelivery_templateId_fkey" FOREIGN KEY ("templateId") REFERENCES "NotificationTemplate"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "NotificationDelivery_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE UNIQUE INDEX "NotificationTemplate_templateKey_key" ON "NotificationTemplate"("templateKey");
CREATE INDEX "NotificationTemplate_channel_status_updatedAt_idx" ON "NotificationTemplate"("channel", "status", "updatedAt");
CREATE UNIQUE INDEX "NotificationDelivery_dedupeKey_key" ON "NotificationDelivery"("dedupeKey");
CREATE INDEX "NotificationDelivery_status_nextAttemptAt_createdAt_idx" ON "NotificationDelivery"("status", "nextAttemptAt", "createdAt");
CREATE INDEX "NotificationDelivery_userId_createdAt_idx" ON "NotificationDelivery"("userId", "createdAt");
CREATE INDEX "NotificationDelivery_channel_status_createdAt_idx" ON "NotificationDelivery"("channel", "status", "createdAt");
